//! bot-db: the database layer of the bot (port of `src/database/client.js` and everything the Prisma client did).
//!
//! * [`models`]: every model and enum of `prisma/schema.prisma` (generated by `rust/fixtures/gen/bot-db-models.mjs`).
//! * [`serde_js`]: JSON exactly like `JSON.stringify` writes it (the Redis cache format).
//! * [`client`]: `DATABASE_URL` parsing (Prisma's query parameters), the pool, `SQL_NOW` / `sql_utc`.
//! * [`query`]: INSERT / UPDATE / SELECT builders that apply Prisma's client-side defaults.
//! * [`tx`]: interactive transactions and the lock patterns the JS uses.
//! * [`migrate`]: a `prisma migrate deploy` compatible migration runner.

pub mod client;
pub mod defaults;
pub mod error;
pub mod ids;
pub mod migrate;
pub mod models;
pub mod query;
pub mod schema;
pub mod seed;
pub mod serde_js;
pub mod tx;

