pub use schema::{ClientDefault, ColumnInfo, EnumInfo, Model, ModelInfo, ScalarKind, model_info};
pub use serde_js::{JsDate, format_js_date, parse_js_date};
pub use tx::{TxOptions, advisory_xact_lock, lock_guild_settings, transaction, try_advisory_xact_lock};

pub use sqlx;
pub use sqlx::PgPool;

/// Quotes an identifier for PostgreSQL (`GuildSettings` -> `"GuildSettings"`).
pub fn quote_ident(name: &str) -> String {
    format!("\"{}\"", name.replace('"', "\"\""))
}
